contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single-entry test: try depositing USDC for a receiver and assert the invariant
    // params: amount to deposit and the receiver address
    function run(uint256 amount, address receiver) public payable {
        require(receiver != address(0), "receiver zero disallowed in precondition");

        // read before values
        uint256 beforeRound = c.currentRound();
        uint256 beforeRoundUsdc = c.roundUsdcBalance();
        uint256 beforeUserUsdc = c.usdcBalance(receiver);

        // attempt the deposit; capture whether it reverted
        bool reverted;
        try c.depositUsdc(amount, receiver) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after values
        uint256 afterRound = c.currentRound();
        uint256 afterRoundUsdc = c.roundUsdcBalance();
        uint256 afterUserUsdc = c.usdcBalance(receiver);

        // General rule asserted:
        // If the call did not revert and amount != 0 then:
        //   - currentRound does not change (depositUsdc shouldn't advance rounds)
        //   - roundUsdcBalance increases by exactly amount
        //   - the receiver's usdcBalance increases by exactly amount
        // Otherwise (if reverted) state must be unchanged for those observables
        assert(
            (reverted && afterRound == beforeRound && afterRoundUsdc == beforeRoundUsdc && afterUserUsdc == beforeUserUsdc)
            ||
            (!reverted && amount != 0 && afterRound == beforeRound && afterRoundUsdc == beforeRoundUsdc + amount && afterUserUsdc == beforeUserUsdc + amount)
        );
    }

    receive() external payable {}
}

