    // Test that calling pauseDeposit from keeper either reverts or results in paused()==true
    // We take no inputs; the keeper must be the caller (this contract). The checker will arrange c such that
    // this contract is or is not the keeper. We only call the external mutating function once.
    function run() public payable {
        // call pauseDeposit and record whether it reverted
        bool didRevert;
        try c.pauseDeposit() {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // After the call: either it reverted, or the contract is paused.
        // Single assert as required.
        assert(didRevert || c.paused() == true);
    }

    receive() external payable {}
}

