contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: try to claim `amount` to `receiver` from `claimer` account context
    // We cannot change msg.sender for calls (InvMutTest is the sender), so we will operate as msg.sender being InvMutTest.
    // Use parameters: receiver address and amount to claim.
    function run(address receiver, uint256 amount) public payable {
        require(receiver != address(0)); // keep inputs sensible so calls don't trivially revert due to receiver==0

        // Read pre-state: unclaimed shares for this contract (claimer = address(this))
        uint256 beforeUnclaimed = c.unclaimedShares(address(this));

        // Try the claim and record whether it reverted
        bool reverted;
        try c.claim(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-state
        uint256 afterUnclaimed = c.unclaimedShares(address(this));

        // If the call reverted, unclaimedShares must be unchanged; if it didn't revert, after = before - amount
        // Use safe comparisons: when not reverted, require before >= amount and after == before - amount.
        if (reverted) {
            assert(afterUnclaimed == beforeUnclaimed);
        } else {
            assert(beforeUnclaimed >= amount && afterUnclaimed == beforeUnclaimed - amount);
        }
    }

    receive() external payable {}
}
